295	// only where whitespace or the end of the text follows. Requiring that keeps
296	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
297	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
298	
299	function endsWithAbbreviation(before) {
300	  const last = before.match(/(\S+)$/);
301	  if (last === null) {
302	    return false;
303	  }
304	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
305	  return ABBREVIATIONS.has(word);
306	}
