  1	const { test } = require('node:test');
  2	const assert = require('node:assert/strict');
  3	const { readingTimeMinutes } = require('../src/textstats');
  4	
  5	// n copies of a one-word token, so the word count is exactly n.
  6	const words = (n) => Array.from({ length: n }, () => 'word').join(' ');
  7	
  8	// A nine-word sentence.
  9	const SENTENCE = 'The lamp keeper climbed the old tower every night.';
 10	
 11	const CASES = [
 12	  ["", null, 0],
 13	  ["x", null, 1],
 14	  ["x x", null, 1],
 15	  ["", 50, 0],
 16	  ["x", 1, 1],
 17	  ["x x", 1, 2],
 18	  ["x x x", 1, 3],
 19	  ["x x x", 2, 2],
 20	];
 21	
 22	test('returns 0 for the empty string', () => {
 23	  assert.equal(readingTimeMinutes(''), 0);
 24	});
 25	
 26	test('returns 0 for whitespace and punctuation only', () => {
 27	  assert.equal(readingTimeMinutes(' \n -- ... '), 0);
 28	});
 29	
 30	test('rounds a single word up to one minute', () => {
 31	  assert.equal(readingTimeMinutes('hello'), 1);
 32	});
 33	
 34	test('returns 1 for exactly 200 words at the default rate', () => {
 35	  assert.equal(readingTimeMinutes(words(200)), 1);
 36	});
 37	
 38	test('returns 2 for 201 words at the default rate', () => {
 39	  assert.equal(readingTimeMinutes(words(201)), 2);
 40	});
 41	
 42	test('returns 2 for exactly 400 words at the default rate', () => {
 43	  assert.equal(readingTimeMinutes(words(400)), 2);
 44	});
 45	
 46	test('throws a TypeError naming the function for a non-string', () => {
 47	  for (const bad of [undefined, null, 12, {}, ['a b']]) {
 48	    assert.throws(() => readingTimeMinutes(bad), (err) => {
 49	      assert.ok(err instanceof TypeError);
 50	      assert.ok(err.message.startsWith('readingTimeMinutes:'));
 51	      return true;
 52	    });
 53	  }
 54	});
 55	
 56	test('matches every row of the reference table', () => {
 57	  for (const [text, wpm, expected] of CASES) {
 58	    const actual = wpm === null ? readingTimeMinutes(text) : readingTimeMinutes(text, wpm);
 59	    assert.equal(actual, expected, JSON.stringify([text, wpm]));
 60	  }
 61	});
 62	
 63	test('counts words across several paragraphs', () => {
 64	  const paragraph = Array.from({ length: 10 }, () => SENTENCE).join(' ');
 65	  const text = [paragraph, paragraph, paragraph].join('\n\n');
 66	  assert.equal(readingTimeMinutes(text), 2);
 67	});
 68	
 69	test('throws a RangeError naming the function for an invalid wpm', () => {
 70	  for (const bad of [0, -1, NaN, Infinity, -Infinity, '200', null]) {
 71	    assert.throws(() => readingTimeMinutes('hello', bad), (err) => {
 72	      assert.ok(err instanceof RangeError, String(bad));
 73	      assert.ok(err.message.startsWith('readingTimeMinutes:'), String(bad));
 74	      return true;
 75	    });
 76	  }
 77	});
 78	
 79	test('accepts a fractional wpm', () => {
 80	  // 301 / 150.5 is exactly 2; one more word tips it to 3. At the default rate
 81	  // both would be 2, so this also shows the fractional rate is used.
 82	  assert.equal(readingTimeMinutes(words(301), 150.5), 2);
 83	  assert.equal(readingTimeMinutes(words(302), 150.5), 3);
 84	});
 85	
 86	test('validates the text before the wpm', () => {
 87	  assert.throws(() => readingTimeMinutes(42, 0), TypeError);
 88	  assert.throws(() => readingTimeMinutes(undefined, NaN), TypeError);
 89	});
 90	
 91	test('defaults wpm to 200 when it is undefined', () => {
 92	  assert.equal(readingTimeMinutes(words(201), undefined), 2);
 93	  assert.equal(readingTimeMinutes(words(200), undefined), 1);
 94	});
 95	
 96	test('counts hyphenated compounds, contractions and decimals as wordCount does', () => {
 97	  // Per Task 1: "well-known" and "don't" are one word each; "3.14" is two (3 and 14). Four words in all.
 98	  assert.equal(readingTimeMinutes('well-known don\'t 3.14', 2), 2);
 99	  assert.equal(readingTimeMinutes('well-known don\'t 3.14', 1), 4);
100	});

